// ============================================================
// Rule: THM_ClickFix Detection
// Vendor: Windows
// Objective:
// Detect activity associated with THM_ClickFix Detection.
// Severity: SEV_040_HIGH
// Category: EXECUTION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0002 - Execution
// Technique: T1059.001 - Command and Scripting Interpreter: PowerShell

// Configuração inicial: define que as comparações não diferenciam maiúsculas/minúsculas  
config case_sensitive = false  

// Fonte de dados: dataset de telemetria de endpoint do Cortex XDR  
// O dataset 'xdr_data' contém eventos brutos coletados pelos agentes instalados  
// nos endpoints (Windows, Linux, macOS), incluindo processos, rede, e alterações de registro  
| dataset = xdr_data  

// Filtro para restringir a eventos provenientes de sistemas operacionais Windows  
// Garante que apenas endpoints com Windows sejam considerados na análise  
| filter agent_os_type = ENUM.AGENT_OS_WINDOWS  

// Filtro para selecionar somente eventos relacionados a alterações no registro do Windows  
// O tipo ENUM.REGISTRY indica eventos de acesso ao registro  
// O subtipo ENUM.REGISTRY_SET_VALUE indica modificação de valores existentes  
| filter event_type = ENUM.REGISTRY  
| filter event_sub_type = ENUM.REGISTRY_SET_VALUE  

// Filtro para restringir o processo responsável pela alteração  
// O processo 'explorer.exe' é o gerenciador de interface do Windows (shell padrão)  
// e normalmente interage com o registro por ações do usuário — aqui, serve para identificar abuso do contexto legítimo  
| filter actor_process_image_name = "explorer.exe"  

// Filtro para detectar alterações específicas na chave de registro 'RunMRU'  
// Essa chave armazena o histórico de comandos executados via "Executar" (Win+R)  
// e pode ser usada para persistência maliciosa ou execução automática de comandos  
| filter action_registry_key_name contains "SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Explorer\\RunMRU"  

// Filtro para detectar conteúdo suspeito dentro dos valores gravados  
// Busca execuções de PowerShell com parâmetros incomuns, como "/bomla"  
// que pode indicar atividade de script ou tentativa de execução automatizada maliciosa  
| filter action_registry_data contains "powershell"  
| filter action_registry_data contains "/bomla"  

// Seleção dos campos relevantes para análise forense e enriquecimento  
| fields agent_id,                                // Identificador único do agente (endpoint)  
         causality_actor_process_image_name,      // Processo raiz da cadeia causal  
         actor_process_image_name,                // Processo que executou a modificação no registro  
         action_registry_key_name,                // Caminho completo da chave de registro alterada  
         action_registry_data,                    // Dados escritos no valor de registro  
         event_sub_type                           // Subtipo de evento do registro (ex: SET_VALUE)
